describe("sailing and docking on the server", () => {
  it("docks at a dock with interact at low speed, records the dock, and casts off on throttle", async () => {
    const host = await track(HeadlessClient.create(endpoint));
    const dock = seaMap.docks.find((each) => each.side === "S")!;
    // One tile out from the dock, at rest.
    await host.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY + 1, heading: 48 });
    host.sendInput({ moveX: 0, moveY: 0, buttons: Buttons.Interact });
    await host.waitFor(() => host.ship()!.dock === dock.id);
    const moored = host.ship()!;
    expect(moored).toMatchObject({ x: dock.tileX * 256 + 128, y: dock.tileY * 256 + 128, speed: 0 });
    // Turning alone does not move a moored ship.
    await host.hold({ moveX: 1, moveY: 0 }, 300);
    expect(host.ship()).toEqual(moored);
    // Astern casts off.
    await host.holdUntil({ moveX: 0, moveY: 1 }, () => host.ship()!.dock === -1 && host.ship()!.y > moored.y);
  });

  it("docks a ship driven into its dock with ahead held and interact tapped, as a player does", async () => {
    const host = await track(HeadlessClient.create(endpoint));
    const dock = seaMap.docks.find((each) => each.side === "S")!;
    // Six tiles south, heading north, full ahead the whole way; interact tapped briefly every 300 ms.
    await host.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY + 6, heading: 48 });
    const deadline = Date.now() + 8000;
    while (host.ship()!.dock !== dock.id && Date.now() < deadline) {
      host.sendInput({ ...AHEAD, buttons: Buttons.Interact });
      await sleep(30);
      for (let beat = 0; beat < 9; beat++) {
        host.sendInput(AHEAD);
        await sleep(30);
      }
    }
    expect(host.ship()).toMatchObject({ x: dock.tileX * 256 + 128, y: dock.tileY * 256 + 128, speed: 0, dock: dock.id });
  });

  it("keeps a ship moored through an input stall, however long, until the player releases or reverses the throttle", async () => {
    const host = await track(HeadlessClient.create(endpoint));
    const dock = seaMap.docks.find((each) => each.side === "S")!;
    const berth = tileCentre(defaultSimulationConfig, dock.tileX, dock.tileY);
    /** Sends a movement every 50 ms for `durationMs` (without releasing it after), checking the ship after each. */
    const keepSending = async (movement: Parameters<HeadlessClient["sendInput"]>[0], durationMs: number, check: () => void = () => {}) => {
      const until = Date.now() + durationMs;
      while (Date.now() < until) {
        host.sendInput(movement);
        await sleep(50);
        check();
      }
    };
    const stayMoored = () => expect(host.ship()).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    /** Docks with ahead and E held, as a player drives in, then stalls with both still held and resumes with E released. */
    const dockThenStall = async () => {
      await host.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY + 2, heading: 48 });
      const deadline = Date.now() + 5000;
      while (host.ship()!.dock !== dock.id) {
        if (Date.now() > deadline) throw new Error("did not dock");
        host.sendInput({ ...AHEAD, buttons: Buttons.Interact });
        await sleep(50);
      }
      await keepSending({ ...AHEAD, buttons: Buttons.Interact }, 200, stayMoored);
      // Nothing from the client for 400 ms: the server's held input lapses after 250 ms (INPUT_HOLD_FRAMES).
      await sleep(400);
      stayMoored();
      // The player's ahead key never went up, so resuming with it held (and E released) is not a fresh press.
      await keepSending(AHEAD, 600, stayMoored);
    };

    await dockThenStall();
    // Astern casts off at once.
    await keepSending({ moveX: 0, moveY: 1 }, 600);
    expect(host.ship()!.dock).toBe(-1);
    // Let go, and let the ship come to rest before placing it again.
    host.sendInput({ moveX: 0, moveY: 0 });
    await host.waitFor(() => host.ship()!.speed === 0);
